div.script:
 //Mostrar u ocultar en funcion de type_id
const typeId = document.getElementById('type_id');
const div_new = document.getElementById('new_data');
const div_alta = document.getElementById('alta_data');
const div_baja = document.getElementById('baja_data');
//Campos new
 const name = document.getElementById('name');
 const identification_id = document.getElementById('identification_id');
 const mobile_phone = document.getElementById('mobile_phone');
 const confidential_compromise = document.getElementById('confidential_compromise');
 const ssnid = document.getElementById('ssnid');
 const work_email = document.getElementById('work_email');
 const salary = document.getElementById('salary');
 const number_of_pays = document.getElementById('number_of_pays');
 const resource_calendar_id = document.getElementById('resource_calendar_id');
 const bank_account = document.getElementById('bank_account');
 const prl_annex = document.getElementById('prl_annex');
 const working_life_report = document.getElementById('working_life_report');
 const cv = document.getElementById('cv');

//Campos alta
 const employee_id_unactive = document.getElementById('employee_id_unactive');
 const alta_date = document.getElementById('alta_date');

//Campos baja
 const employee_id_active = document.getElementById('employee_id_active');
 const baja_date = document.getElementById('baja_date');
 const baja_reason = document.getElementById('baja_reason');
 const baja_notes = document.getElementById('baja_notes');

typeId.addEventListener('change', function () {
    if (typeId.value === 'new') {
        div_new.style.display = 'block';
        //CAMPOS
        name.setAttribute('name', 'name') ;
        name.setAttribute('required', '') ;
        identification_id.setAttribute('name', 'identification_id') ;
        identification_id.setAttribute('required', '') ;
        mobile_phone.setAttribute('name', 'mobile_phone') ;
        mobile_phone.setAttribute('required', '') ;
        confidential_compromise.setAttribute('name', 'confidential_compromise') ;
        ssnid.setAttribute('name', 'ssnid') ;
        ssnid.setAttribute('required', '') ;
        work_email.setAttribute('name', 'work_email') ;
        work_email.setAttribute('required', '') ;
        salary.setAttribute('name', 'salary') ;
        number_of_pays.setAttribute('name', 'number_of_pays') ;
        resource_calendar_id.setAttribute('name', 'resource_calendar_id') ;
        bank_account.setAttribute('name', 'bank_account') ;
        bank_account.setAttribute('required', '') ;
        prl_annex.setAttribute('name', 'prl_annex') ;
        working_life_report.setAttribute('name', 'working_life_report') ;
        cv.setAttribute('name', 'cv') ;

        div_alta.style.display = 'none';
        //Campos
        employee_id_unactive.removeAttribute('name') ;
        employee_id_unactive.removeAttribute('required') ;
        alta_date.removeAttribute('name') ;
        alta_date.removeAttribute('required') ;

        div_baja.style.display = 'none';
        //Campos
        employee_id_active.removeAttribute('name') ;
        employee_id_active.removeAttribute('required') ;
        baja_date.removeAttribute('name') ;
        baja_date.removeAttribute('required') ;
        baja_reason.removeAttribute('name') ;
        baja_reason.removeAttribute('required') ;
        baja_notes.removeAttribute('name') ;

    } else if (typeId.value === 'alta') {
        div_new.style.display = 'none';
        //Campos
        name.removeAttribute('name') ;
        name.removeAttribute('required') ;
        identification_id.removeAttribute('name') ;
        identification_id.removeAttribute('required') ;
        mobile_phone.removeAttribute('name') ;
        mobile_phone.removeAttribute('required') ;
        confidential_compromise.removeAttribute('name') ;
        ssnid.removeAttribute('name') ;
        ssnid.removeAttribute('required') ;
        work_email.removeAttribute('name') ;
        work_email.removeAttribute('required') ;
        salary.removeAttribute('name') ;
        number_of_pays.removeAttribute('name') ;
        resource_calendar_id.removeAttribute('name') ;
        bank_account.removeAttribute('name') ;
        bank_account.removeAttribute('required') ;
        prl_annex.removeAttribute('name') ;
        working_life_report.removeAttribute('name') ;
        cv.removeAttribute('name') ;

        div_alta.style.display = 'block';
        //Campos
        employee_id_unactive.setAttribute('name', 'employee_id_unactive') ;
        employee_id_unactive.setAttribute('required', '') ;
        alta_date.setAttribute('name', 'alta_date') ;
        alta_date.setAttribute('required', '') ;

        div_baja.style.display = 'none';
        //Campos
        employee_id_active.removeAttribute('name') ;
        employee_id_active.removeAttribute('required') ;
        baja_date.removeAttribute('name') ;
        baja_date.removeAttribute('required') ;
        baja_reason.removeAttribute('name') ;
        baja_reason.removeAttribute('required') ;
        baja_notes.removeAttribute('name') ;


    }else if (typeId.value === 'baja') {
        div_new.style.display = 'none';
        //Campos
        name.removeAttribute('name') ;
        name.removeAttribute('required') ;
        identification_id.removeAttribute('name') ;
        identification_id.removeAttribute('required') ;
        mobile_phone.removeAttribute('name') ;
        mobile_phone.removeAttribute('required') ;
        confidential_compromise.removeAttribute('name') ;
        ssnid.removeAttribute('name') ;
        ssnid.removeAttribute('required') ;
        work_email.removeAttribute('name') ;
        work_email.removeAttribute('required') ;
        salary.removeAttribute('name') ;
        number_of_pays.removeAttribute('name') ;
        resource_calendar_id.removeAttribute('name') ;
        bank_account.removeAttribute('name') ;
        bank_account.removeAttribute('required') ;
        prl_annex.removeAttribute('name') ;
        working_life_report.removeAttribute('name') ;
        cv.removeAttribute('name') ;

        div_alta.style.display = 'none';
        //Campos
        employee_id_unactive.removeAttribute('name') ;
        employee_id_unactive.removeAttribute('required') ;
        alta_date.removeAttribute('name') ;
        alta_date.removeAttribute('required') ;

        div_baja.style.display = 'block';
        //Campos
        employee_id_active.setAttribute('name', 'employee_id_active') ;
        employee_id_active.setAttribute('required', '') ;
        baja_date.setAttribute('name', 'baja_date') ;
        baja_date.setAttribute('required', '') ;
        baja_reason.setAttribute('name', 'baja_reason') ;
        baja_reason.setAttribute('required', '') ;
        baja_notes.setAttribute('name', 'baja_notes') ;

}
});

 //PARTE DE RELLENAR EMPLEADOS inactivos CON AJAX
document.addEventListener('DOMContentLoaded', function () {
    const companySelect = document.getElementById('company_id');
    const employeeSelectUnactive = document.getElementById('employee_id_unactive');
    const employeeSelectActive = document.getElementById('employee_id_active');

    companySelect.addEventListener('change', function () {
        const companyId = companySelect.value;
        employeeSelectUnactive.innerHTML = 'Loading...';
        employeeSelectActive.innerHTML = 'Loading...';
        $.ajax({
            url: '/get_employee_by_company',
            type: 'GET',
            data: {
                company_id: companyId,
                employee_type: "employee",
                active: 0
            }, // Pasar el company_id como parámetro
            success: function(response) {
                var employeeSelectUnactive = document.getElementById("employee_id_unactive");
                employeeSelectUnactive.innerHTML = '';
                let employees = response.partners.employees;
                if (employees.length === 0) {
                    const option = document.createElement('option');
                    option.value = '0';
                    option.textContent = 'employee not found';
                    employeeSelectUnactive.appendChild(option);
                } else {
                    employees.forEach(function(employee) {
                        const option = document.createElement('option');
                        option.value = employee.id;
                        option.textContent = employee.name;
                        employeeSelectUnactive.appendChild(option);
                    });
                }
            },
            error: function(error) {
                console.log("Error fetching employees: ", error);
            }
        });
        $.ajax({
            url: '/get_employee_by_company',
            type: 'GET',
            data: {
                company_id: companyId,
                employee_type: "employee",
                active: 1
            }, // Pasar el company_id como parámetro
            success: function(response) {
                var employeeSelectActive = document.getElementById("employee_id_active");
                employeeSelectActive.innerHTML = '';
                let employees = response.partners.employees;
                if (employees.length === 0) {
                    const option = document.createElement('option');
                    option.value = '0';
                    option.textContent = 'employee not found';
                    employeeSelectActive.appendChild(option);
                } else {
                    employees.forEach(function(employee) {
                        const option = document.createElement('option');
                        option.value = employee.id;
                        option.textContent = employee.name;
                        employeeSelectActive.appendChild(option);
                    });
                }
            },
            error: function(error) {
                console.log("Error fetching employees: ", error);
            }
        });
    });
});
